namespace Mode.Domain.Files;

/// <summary>Where file bytes live. Keys are generated by Mode (letters, digits, '/', '-', '_', '.') and never contain user input.</summary>
public interface IFileStore
{
    /// <summary>Writes the whole stream; the object becomes visible only after a complete write.</summary>
    Task WriteAsync(string key, Stream content, CancellationToken cancellationToken);

    /// <summary>Null when the object does not exist.</summary>
    Task<Stream?> OpenReadAsync(string key, CancellationToken cancellationToken);

    Task<long?> GetSizeAsync(string key, CancellationToken cancellationToken);

    /// <summary>No error if the object is already gone.</summary>
    Task DeleteAsync(string key, CancellationToken cancellationToken);
}
